def count_sequences(n, last, memo):
    if last in memo:
        return memo[last]
    if last == n:
        return 1
    count = 0
    for i in range(1, last):
        if i <= last // 2:
            count += count_sequences(n, i, memo)
    memo[last] = count
    return count
