def calculate_score(system: int, points: str) -> list:
    games = []
    player_score = 0
    opponent_score = 0
    for player_point in points:
        if player_point == "W":
            player_score += 1
        else:
            opponent_score += 1
        if player_score == system and player_score >= opponent_score + 2:
            games.append(f"{player_score}:{opponent_score}")
            player_score = 0
            opponent_score = 0
    if player_score > opponent_score:
        games.append(f"{player_score}:{opponent_score}")
    return games
